def safe_json_path_lookup(data: dict | list, path: str, default: any = None) -> any:
    if not path:
        return data
    components = path.split('.')
    for component in components:
        if component.isdigit():
            try:
                data = data[int(component)]
            except (IndexError, TypeError):
                return default
        else:
            try:
                data = data[component]
            except (KeyError, TypeError):
                return default
    return data

