def fuzzy_search_score(pattern: str, text: str) -> int:
    if not pattern:
        return 0
    if not text:
        return 0

    pattern = pattern.lower()
    text = text.lower()
    pattern_len = len(pattern)
    text_len = len(text)
    score = 0
    i, j = 0, 0

    while i < pattern_len and j < text_len:
        if pattern[i] == text[j]:
            score += 10
            if i > 0 and j > 0 and j == text.find(pattern[i], j - 1) + 1:
                score += 15
            if j == 0 or text[j - 1] in " _-":
                score += 20
            i += 1
        j += 1

    return score if i == pattern_len else 0

