from typing import List
import heapq

def sliding_window_median(nums: List[float], k: int) -> List[float]:
    if k <= 0 or k > len(nums):
        return []

    result = []
    max_heap = []
    min_heap = []

    for i, num in enumerate(nums):
        if not max_heap or num <= -max_heap[0]:
            heapq.heappush(max_heap, -num)
        else:
            heapq.heappush(min_heap, num)

        # Balance the heaps
        if len(max_heap) > len(min_heap) + 1:
            heapq.heappush(min_heap, -heapq.heappop(max_heap))
        elif len(min_heap) > len(max_heap):
            heapq.heappush(max_heap, -heapq.heappop(min_heap))

        # Remove the element that is out of the window
        if i >= k:
            if nums[i - k] <= -max_heap[0]:
                if nums[i - k] == -max_heap[0]:
                    heapq.heappop(max_heap)
                else:
                    max_heap.remove(-nums[i - k])
                    heapq.heapify(max_heap)
            else:
                if nums[i - k] == min_heap[0]:
                    heapq.heappop(min_heap)
                else:
                    min_heap.remove(nums[i - k])
                    heapq.heapify(min_heap)

        # Calculate the median
        if i >= k - 1:
            if len(max_heap) == len(min_heap):
                median = (-max_heap[0] + min_heap[0]) / 2
            else:
                median = -max_heap[0]
            result.append(round(median, 2))

    return result

